sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_receita_primaria_total": "receita_primaria",
       "v_despesa_primaria_total": "despesa_primaria",
       "v_resultado_primario_receita_despesa": "resultado_primario",
       "v_bimestre_de_referencia_1_6": "bimestre",
       "v_rpps_regime_proprio_de_previdencia_social": "rpps",
       "v_ano": "ano"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
            fieldMapping[questionName] = value;
            if(fieldMapping[questionName] == 'v_rpps_regime_proprio_de_previdencia_social'){
                if(value == 'Yes'){
                    fieldMapping[questionName] == true;
                } else {
                    fieldMapping[questionName] == false;
                }
            }
       }
   }

outputs.receita_primaria = fieldMapping['v_receita_primaria_total'];
outputs.despesa_primaria = fieldMapping['v_despesa_primaria_total'];
outputs.resultado_primario = fieldMapping['v_resultado_primario_receita_despesa'];
outputs.bimestre = fieldMapping['v_bimestre_de_referencia_1_6'];
outputs.rpps = fieldMapping['v_rpps_regime_proprio_de_previdencia_social'];
outputs.ano = fieldMapping['v_ano'];

})(inputs, outputs);

